import{_ as c,r as t,o as l,c as u,e as p,a as s,s as i,d as a}from"./chunks/framework.CXcwiNg-.js";const q=JSON.parse('{"title":"Конструктор запросов - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":3,"title":"Пример необработанного SQL","slug":"пример-необработанного-sql","link":"#пример-необработанного-sql","children":[]},{"level":2,"title":"Получение результатов","slug":"получение-результатов","link":"#получение-результатов","children":[{"level":3,"title":"Извлечение значений","slug":"извлечение-значении","link":"#извлечение-значении","children":[]},{"level":3,"title":"Разбиение результатов на части","slug":"разбиение-результатов-на-части","link":"#разбиение-результатов-на-части","children":[]},{"level":3,"title":"Агрегатные функции","slug":"агрегатные-функции","link":"#агрегатные-функции","children":[]}]},{"level":2,"title":"Операторы Select","slug":"операторы-select","link":"#операторы-select","children":[{"level":3,"title":"Необработанные выражения","slug":"необработанные-выражения","link":"#необработанные-выражения","children":[]},{"level":3,"title":"Необработанные методы","slug":"необработанные-методы","link":"#необработанные-методы","children":[]}]},{"level":2,"title":"Соединения (Joins)","slug":"соединения-joins","link":"#соединения-joins","children":[{"level":3,"title":"Расширенные операторы соединения","slug":"расширенные-операторы-соединения","link":"#расширенные-операторы-соединения","children":[]},{"level":3,"title":"Соединения с подзапросами","slug":"соединения-с-подзапросами","link":"#соединения-с-подзапросами","children":[]},{"level":3,"title":"Объединения (Unions)","slug":"объединения-unions","link":"#объединения-unions","children":[]}]},{"level":2,"title":"Условия Where","slug":"условия-where","link":"#условия-where","children":[{"level":3,"title":"Операторы Or","slug":"операторы-or","link":"#операторы-or","children":[]},{"level":3,"title":"Дополнительные операторы Where","slug":"дополнительные-операторы-where","link":"#дополнительные-операторы-where","children":[]},{"level":3,"title":"Оператор поиска","slug":"оператор-поиска","link":"#оператор-поиска","children":[]}]},{"level":2,"title":"Составные условия Where","slug":"составные-условия-where","link":"#составные-условия-where","children":[{"level":3,"title":"Операторы Exists","slug":"операторы-exists","link":"#операторы-exists","children":[]},{"level":3,"title":"JSON-условия Where","slug":"json-условия-where","link":"#json-условия-where","children":[]},{"level":3,"title":"Условные предложения","slug":"условные-предложения","link":"#условные-предложения","children":[]}]},{"level":2,"title":"Сортировка, группировка, ограничение","slug":"сортировка-группировка-ограничение","link":"#сортировка-группировка-ограничение","children":[{"level":3,"title":"Сортировка","slug":"сортировка","link":"#сортировка","children":[]},{"level":3,"title":"Группировка","slug":"группировка","link":"#группировка","children":[]},{"level":3,"title":"Ограничение и смещение","slug":"ограничение-и-смещение","link":"#ограничение-и-смещение","children":[]}]},{"level":2,"title":"Вставка","slug":"вставка","link":"#вставка","children":[{"level":3,"title":"Автоинкрементные ID","slug":"автоинкрементные-id","link":"#автоинкрементные-id","children":[]}]},{"level":2,"title":"Обновление","slug":"обновление","link":"#обновление","children":[{"level":3,"title":"Обновление или вставка","slug":"обновление-или-вставка","link":"#обновление-или-вставка","children":[]},{"level":3,"title":"Upsert","slug":"upsert","link":"#upsert","children":[]},{"level":3,"title":"Обновление JSON-столбцов","slug":"обновление-json-столбцов","link":"#обновление-json-столбцов","children":[]},{"level":3,"title":"Инкремент / Декремент","slug":"инкремент-декремент","link":"#инкремент-декремент","children":[]}]},{"level":2,"title":"Удаление","slug":"удаление","link":"#удаление","children":[]},{"level":2,"title":"Пессимистическая блокировка","slug":"пессимистическая-блокировка","link":"#пессимистическая-блокировка","children":[]},{"level":2,"title":"Кэширование запросов","slug":"кэширование-запросов","link":"#кэширование-запросов","children":[]},{"level":2,"title":"Отладка","slug":"отладка","link":"#отладка","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}],"relativePath":"3.x/ru/extend/database/query.md","filePath":"3.x/ru/extend/database/query.md"}'),r={name:"3.x/ru/extend/database/query.md"};function k(g,n,d,h,b,f){const e=t("pre-heading"),o=t("post-heading");return l(),u("div",null,[p(e),n[0]||(n[0]=s("h1",null,"Конструктор запросов",-1)),p(o),n[1]||(n[1]=i(`<div class="custom-block aside"><p>Конструктор запросов использует привязку параметров PDO для защиты вашего приложения от атак SQL-инъекций. Нет необходимости очищать строки, передаваемые как привязки.</p></div><p>Конструктор запросов к базе данных предоставляет удобный, гибкий интерфейс для создания и выполнения запросов к базе данных. Он может использоваться для выполнения большинства операций с базой данных в вашем приложении и работает на всех поддерживаемых системах баз данных.</p><h3 id="пример-необработанного-sql"><a href="#пример-необработанного-sql" class="header-anchor">#</a> Пример необработанного SQL</h3><p>Иногда имеет больше смысла выполнить запрос с использованием чистого SQL, вы можете сделать это с помощью метода <code>Db::select</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select * from sometable where name = :name&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Charles&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Подробнее смотрите статью о <a href="./basics.html">выполнении необработанных SQL-запросов</a>.</p><h2 id="получение-результатов"><a href="#получение-результатов" class="header-anchor">#</a> Получение результатов</h2><p>Для начала формирования запроса используйте метод <code>table</code> фасада <code>Db</code>. Метод <code>table</code> возвращает экземпляр конструктора запросов для указанной таблицы, позволяя цепочкой добавлять ограничения к запросу и, наконец, получать результаты. В этом примере <code>get</code> вернёт все записи из таблицы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Аналогично <a href="./basics.html">необработанным запросам</a>, метод <code>get</code> возвращает <code>array</code> результатов, где каждый результат является экземпляром PHP-объекта <code>stdClass</code>. Вы можете получить значение каждого столбца, обращаясь к столбцу как к свойству объекта.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Если вам нужно получить только одну строку из таблицы базы данных, используйте метод <code>first</code>. Этот метод вернёт один объект <code>stdClass</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;John&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">echo</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="извлечение-значении"><a href="#извлечение-значении" class="header-anchor">#</a> Извлечение значений</h3><p>Если вам не нужна вся строка целиком, вы можете извлечь одно значение из записи с помощью метода <code>value</code>. Этот метод вернёт значение столбца напрямую:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$email</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;John&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">value</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы хотите получить массив, содержащий значения одного столбца, используйте метод <code>pluck</code>. В этом примере мы получим массив названий ролей.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$titles</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;roles&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">pluck</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$titles</span> <span class="token keyword">as</span> <span class="token variable">$title</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$title</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы также можете указать пользовательский столбец-ключ для возвращаемого массива.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$roles</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;roles&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">pluck</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$roles</span> <span class="token keyword">as</span> <span class="token variable">$name</span> <span class="token operator">=&gt;</span> <span class="token variable">$title</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$title</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block warning"><p>Результат <code>pluck</code> возвращает объект <code>Collection</code>, который ведёт себя как массив. Используйте метод <code>all()</code> для преобразования его в PHP-массив, например: <code>pluck(&#39;name&#39;)-&gt;all()</code>.</p></div><h3 id="разбиение-результатов-на-части"><a href="#разбиение-результатов-на-части" class="header-anchor">#</a> Разбиение результатов на части</h3><p>Если вам нужно работать с тысячами записей базы данных, рассмотрите использование метода <code>chunk</code>. Этот метод получает небольшую «часть» результатов за раз и передаёт каждую часть в <code>Closure</code> для обработки. Этот метод очень полезен при написании <a href="./../console-commands.html">консольных команд</a>, обрабатывающих тысячи записей. Например, обработаем всю таблицу <code>users</code> частями по 100 записей.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">chunk</span><span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$users</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">//</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете остановить обработку дальнейших частей, вернув <code>false</code> из <code>Closure</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">chunk</span><span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$users</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Process the records...</span>

    <span class="token keyword">return</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы обновляете записи базы данных при разбиении на части, результаты могут измениться неожиданным образом. Поэтому при обновлении записей во время разбиения лучше всего использовать метод <code>chunkById</code>. Этот метод автоматически пагинирует результаты на основе первичного ключа записи.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">false</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">chunkById</span><span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$users</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
                <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">)</span>
                <span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;active&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>При обновлении или удалении записей внутри callback-функции chunk любые изменения первичного ключа или внешних ключей могут повлиять на запрос chunk. Это потенциально может привести к тому, что записи не будут включены в результаты разбиения.</p></div><h3 id="агрегатные-функции"><a href="#агрегатные-функции" class="header-anchor">#</a> Агрегатные функции</h3><p>Конструктор запросов также предоставляет множество агрегатных методов, таких как <code>count</code>, <code>max</code>, <code>min</code>, <code>avg</code> и <code>sum</code>. Вы можете вызвать любой из этих методов после построения запроса:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">count</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$price</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;price&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Конечно, вы можете комбинировать эти методы с другими условиями для построения запроса:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$price</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_finalized&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">avg</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;price&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вместо использования метода <code>count</code> для определения наличия записей, соответствующих ограничениям запроса, вы можете использовать методы <code>exists</code> и <code>doesntExist</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;finalized&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">exists</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;finalized&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">doesntExist</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="операторы-select"><a href="#операторы-select" class="header-anchor">#</a> Операторы Select</h2><p>В некоторых случаях вам может не понадобиться выбирать все столбцы из таблицы базы данных. С помощью метода <code>select</code> вы можете указать пользовательское предложение <code>select</code> для запроса.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;email as user_email&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>distinct</code> позволяет принудительно вернуть только уникальные результаты запроса.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">distinct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если у вас уже есть экземпляр конструктора запросов и вы хотите добавить столбец к существующему предложению select, используйте метод <code>addSelect</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$query</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">addSelect</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;age&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="необработанные-выражения"><a href="#необработанные-выражения" class="header-anchor">#</a> Необработанные выражения</h3><p>Иногда вам может понадобиться использовать необработанное выражение в запросе. Для создания необработанного выражения используйте метод <code>Db::raw</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;count(*) as user_count, status&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;status&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&lt;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">groupBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;status&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Другое использование — конкатенация столбцов и/или строк.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token string double-quoted-string">&quot;(first_name, &#39; &#39;, last_name) as full_name&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>Необработанные выражения будут вставлены в запрос как строки, поэтому будьте крайне осторожны, чтобы не создать уязвимости SQL-инъекций.</p></div><h3 id="необработанные-методы"><a href="#необработанные-методы" class="header-anchor">#</a> Необработанные методы</h3><p>Вместо использования <code>Db::raw</code> вы также можете использовать следующие методы для вставки необработанного выражения в различные части запроса.</p><p>Метод <code>selectRaw</code> можно использовать вместо <code>addSelect(Db::raw(...))</code>. Этот метод принимает необязательный массив привязок в качестве второго аргумента:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$orders</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">selectRaw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;price * ? as price_with_tax&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1.0825</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Методы <code>whereRaw</code> и <code>orWhereRaw</code> можно использовать для вставки необработанного условия <code>where</code> в запрос. Эти методы принимают необязательный массив привязок в качестве второго аргумента:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$orders</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereRaw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;price &gt; IF(state = &quot;TX&quot;, ?, 100)&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">200</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Методы <code>havingRaw</code> и <code>orHavingRaw</code> можно использовать для установки необработанной строки в качестве значения предложения <code>having</code>. Эти методы принимают необязательный массив привязок в качестве второго аргумента:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$orders</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;department&#39;</span><span class="token punctuation">,</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;SUM(price) as total_sales&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">groupBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;department&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">havingRaw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;SUM(price) &gt; ?&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">2500</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>orderByRaw</code> можно использовать для установки необработанной строки в качестве значения предложения order by:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$orders</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">orderByRaw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;updated_at - created_at DESC&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>groupByRaw</code> можно использовать для установки необработанной строки в качестве значения предложения group by:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$orders</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;city&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;state&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">groupByRaw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;city, state&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="соединения-joins"><a href="#соединения-joins" class="header-anchor">#</a> Соединения (Joins)</h2><p>Конструктор запросов также может использоваться для написания операторов соединения. Для выполнения базового SQL «inner join» используйте метод <code>join</code> на экземпляре конструктора запросов. Первый аргумент, передаваемый методу <code>join</code>, — это имя таблицы, к которой нужно присоединиться, а остальные аргументы указывают ограничения столбцов для соединения. Конечно, как видите, вы можете присоединить несколько таблиц в одном запросе.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;contacts&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;users.id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;contacts.user_id&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;users.id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;orders.user_id&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users.*&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;contacts.phone&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;orders.price&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы хотите выполнить «left join» или «right join» вместо «inner join», используйте метод <code>leftJoin</code> или <code>rightJoin</code>. Методы <code>leftJoin</code> и <code>rightJoin</code> имеют ту же сигнатуру, что и метод <code>join</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">leftJoin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;users.id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;posts.user_id&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">rightJoin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;users.id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;posts.user_id&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для выполнения «cross join» используйте метод <code>crossJoin</code> с именем таблицы, к которой хотите выполнить перекрёстное соединение. Перекрёстные соединения генерируют декартово произведение между первой таблицей и присоединённой таблицей.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;sizes&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">crossJoin</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;colors&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="расширенные-операторы-соединения"><a href="#расширенные-операторы-соединения" class="header-anchor">#</a> Расширенные операторы соединения</h3><p>Вы также можете указать более сложные условия соединения. Для начала передайте <code>Closure</code> в качестве второго аргумента метода <code>join</code>. <code>Closure</code> получит объект <code>JoinClause</code>, позволяющий указать ограничения для предложения <code>join</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;contacts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$join</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$join</span><span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users.id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;contacts.user_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">orOn</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы хотите использовать условие в стиле «where» в соединениях, используйте методы <code>where</code> и <code>orWhere</code> для соединения. Вместо сравнения двух столбцов эти методы сравнивают столбец со значением.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;contacts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$join</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$join</span><span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users.id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;contacts.user_id&#39;</span><span class="token punctuation">)</span>
            <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;contacts.user_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="соединения-с-подзапросами"><a href="#соединения-с-подзапросами" class="header-anchor">#</a> Соединения с подзапросами</h3><p>Вы можете использовать методы <code>joinSub</code>, <code>leftJoinSub</code> и <code>rightJoinSub</code> для присоединения запроса к подзапросу. Каждый из этих методов принимает три аргумента: подзапрос, его псевдоним таблицы и Closure, определяющую связанные столбцы:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$latestPosts</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">,</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;MAX(created_at) as last_post_created_at&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_published&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">groupBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">joinSub</span><span class="token punctuation">(</span><span class="token variable">$latestPosts</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;latest_posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$join</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$join</span><span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users.id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;latest_posts.user_id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="объединения-unions"><a href="#объединения-unions" class="header-anchor">#</a> Объединения (Unions)</h3><p>Конструктор запросов также предоставляет быстрый способ «объединения» двух запросов. Например, вы можете создать начальный запрос, а затем использовать метод <code>union</code> для объединения со вторым запросом.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$first</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereNull</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereNull</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;last_name&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">union</span><span class="token punctuation">(</span><span class="token variable">$first</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>unionAll</code> также доступен и имеет ту же сигнатуру, что и <code>union</code>.</p><h2 id="условия-where"><a href="#условия-where" class="header-anchor">#</a> Условия Where</h2><p>Для добавления условий <code>where</code> к запросу используйте метод <code>where</code> экземпляра конструктора запросов. Базовый вызов <code>where</code> требует три аргумента. Первый аргумент — имя столбца. Второй аргумент — оператор, который может быть любым из поддерживаемых операторов базы данных. Третий аргумент — значение для сравнения со столбцом.</p><p>Например, вот запрос, проверяющий, что значение столбца «votes» равно 100.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для удобства, если вы просто хотите проверить равенство столбца заданному значению, вы можете передать значение напрямую вторым аргументом метода <code>where</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете использовать различные другие операторы при написании условия <code>where</code>, например, больше <code>&gt;</code>, не равно <code>&lt;&gt;</code> и <code>like</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;=&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&lt;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;like&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;T%&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="операторы-or"><a href="#операторы-or" class="header-anchor">#</a> Операторы Or</h3><p>Вы можете объединять условия where в цепочку, а также добавлять условия <code>or</code> к запросу. Метод <code>orWhere</code> принимает те же аргументы, что и метод <code>where</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">orWhere</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;John&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Вы также можете добавить префикс <code>or</code> к любому из нижеприведённых методов where, чтобы сделать условие условием «OR» — например, <code>orWhereBetween</code>, <code>orWhereIn</code> и т.д.</p></div><h3 id="дополнительные-операторы-where"><a href="#дополнительные-операторы-where" class="header-anchor">#</a> Дополнительные операторы Where</h3><p>Метод <code>whereBetween</code> проверяет, что значение столбца находится между двумя значениями.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereBetween</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>whereNotBetween</code> проверяет, что значение столбца лежит за пределами двух значений.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereNotBetween</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>whereIn</code> проверяет, что значение данного столбца содержится в указанном массиве.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>whereNotIn</code> проверяет, что значение данного столбца <strong>не</strong> содержится в указанном массиве.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereNotIn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>whereNull</code> проверяет, что значение данного столбца равно <code>NULL</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereNull</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;updated_at&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>whereNotNull</code> проверяет, что значение столбца <strong>не</strong> равно <code>NULL</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereNotNull</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;updated_at&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="оператор-поиска"><a href="#оператор-поиска" class="header-anchor">#</a> Оператор поиска</h3><p>Методы <code>searchWhere</code> и <code>orSearchWhere</code> могут использоваться для выполнения поискового запроса по значению столбца. Метод добавляет к запросу условие, используя поисковый термин (первый аргумент) и столбцы поиска (второй аргумент) с помощью регистронезависимого запроса <code>like</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$pages</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">searchWhere</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo bar&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;content&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Приведённый выше пример сформирует следующий SQL, где к каждому столбцу и значению применяется <code>lower()</code>:</p><div class="language-sql extra-class"><pre class="language-sql"><code><span class="token keyword">select</span> <span class="token operator">*</span> <span class="token keyword">from</span> users <span class="token keyword">where</span>
    <span class="token punctuation">(</span>title <span class="token operator">like</span> <span class="token string">&#39;%foo%&#39;</span> <span class="token operator">and</span> title <span class="token operator">like</span> <span class="token string">&#39;%bar%&#39;</span><span class="token punctuation">)</span> <span class="token operator">or</span>
    <span class="token punctuation">(</span>content <span class="token operator">like</span> <span class="token string">&#39;%foo%&#39;</span> <span class="token operator">and</span> content <span class="token operator">like</span> <span class="token string">&#39;%bar%&#39;</span><span class="token punctuation">)</span>
</code></pre></div><p>По умолчанию каждое слово в поисковом термине будет искаться, однако вы можете изменить это поведение, указав режим (третий аргумент), со следующими поддерживаемыми режимами.</p><ul><li><strong>all</strong>: результат должен содержать все слова (по умолчанию)</li><li><strong>any</strong>: результат может содержать любое слово</li><li><strong>exact</strong>: результат должен содержать точную фразу</li></ul><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">searchWhere</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo bar&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;content&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;exact&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Пример поиска <code>exact</code> выше сформирует следующий SQL:</p><div class="language-sql extra-class"><pre class="language-sql"><code><span class="token keyword">select</span> <span class="token operator">*</span> <span class="token keyword">from</span> users <span class="token keyword">where</span> <span class="token punctuation">(</span>title <span class="token operator">like</span> <span class="token string">&#39;%foo bar%&#39;</span> <span class="token operator">or</span> content <span class="token operator">like</span> <span class="token string">&#39;%foo bar%&#39;</span><span class="token punctuation">)</span>
</code></pre></div><h2 id="составные-условия-where"><a href="#составные-условия-where" class="header-anchor">#</a> Составные условия Where</h2><p>Иногда вам может понадобиться создать более сложные условия where, такие как «where exists» или вложенные группы параметров. Конструктор запросов Laravel может обрабатывать и эти случаи. Для начала рассмотрим пример группировки ограничений в скобках:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;=&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;John&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">orWhere</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span>
            <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&lt;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Admin&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Как видите, передача <code>Closure</code> в метод <code>orWhere</code> указывает конструктору запросов начать группу ограничений. <code>Closure</code> получит экземпляр конструктора запросов, который вы можете использовать для установки ограничений, которые должны содержаться внутри группы скобок. Приведённый выше пример сформирует следующий SQL:</p><div class="language-sql extra-class"><pre class="language-sql"><code><span class="token keyword">select</span> <span class="token operator">*</span> <span class="token keyword">from</span> users <span class="token keyword">where</span> name <span class="token operator">=</span> <span class="token string">&#39;John&#39;</span> <span class="token operator">or</span> <span class="token punctuation">(</span>votes <span class="token operator">&gt;</span> <span class="token number">100</span> <span class="token operator">and</span> title <span class="token operator">&lt;&gt;</span> <span class="token string">&#39;Admin&#39;</span><span class="token punctuation">)</span>
</code></pre></div><h3 id="операторы-exists"><a href="#операторы-exists" class="header-anchor">#</a> Операторы Exists</h3><p>Метод <code>whereExists</code> позволяет писать SQL-условия <code>where exists</code>. Метод <code>whereExists</code> принимает аргумент <code>Closure</code>, который получит экземпляр конструктора запросов, позволяющий определить запрос, который должен быть помещён внутри условия «exists»:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereExists</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
            <span class="token operator">-&gt;</span><span class="token function">from</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders&#39;</span><span class="token punctuation">)</span>
            <span class="token operator">-&gt;</span><span class="token function">whereRaw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;orders.user_id = users.id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Запрос выше сформирует следующий SQL:</p><div class="language-sql extra-class"><pre class="language-sql"><code><span class="token keyword">select</span> <span class="token operator">*</span> <span class="token keyword">from</span> users <span class="token keyword">where</span> <span class="token keyword">exists</span> <span class="token punctuation">(</span>
    <span class="token keyword">select</span> <span class="token number">1</span> <span class="token keyword">from</span> orders <span class="token keyword">where</span> orders<span class="token punctuation">.</span>user_id <span class="token operator">=</span> users<span class="token punctuation">.</span>id
<span class="token punctuation">)</span>
</code></pre></div><h3 id="json-условия-where"><a href="#json-условия-where" class="header-anchor">#</a> JSON-условия Where</h3><p>October CMS также поддерживает запросы к столбцам типа JSON в базах данных, которые поддерживают типы столбцов JSON. Для запроса к JSON-столбцу используйте оператор <code>-&gt;</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;options-&gt;language&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;en&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;preferences-&gt;dining-&gt;meal&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;salad&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете использовать <code>whereJsonContains</code> для запроса JSON-массивов (не поддерживается в SQLite).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereJsonContains</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;options-&gt;languages&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;en&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>MySQL и PostgreSQL поддерживают <code>whereJsonContains</code> с несколькими значениями.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereJsonContains</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;options-&gt;languages&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;en&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;de&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете использовать <code>whereJsonLength</code> для запроса JSON-массивов по их длине.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereJsonLength</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;options-&gt;languages&#39;</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">whereJsonLength</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;options-&gt;languages&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="условные-предложения"><a href="#условные-предложения" class="header-anchor">#</a> Условные предложения</h3><p>Иногда вам может понадобиться, чтобы условия применялись к запросу только при выполнении определённого условия. Например, вы можете захотеть применить оператор <code>where</code> только если определённое входное значение присутствует во входящем запросе. Вы можете сделать это с помощью метода <code>when</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$role</span> <span class="token operator">=</span> <span class="token variable">$request</span><span class="token operator">-&gt;</span><span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;role&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">when</span><span class="token punctuation">(</span><span class="token variable">$role</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$role</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;role_id&#39;</span><span class="token punctuation">,</span> <span class="token variable">$role</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>when</code> выполняет заданное Closure только когда первый параметр равен <code>true</code>. Если первый параметр равен <code>false</code>, Closure не будет выполнено.</p><p>Вы можете передать другое Closure в качестве третьего параметра метода <code>when</code>. Это Closure будет выполнено, если первый параметр оценивается как false. Чтобы проиллюстрировать использование этой функции, мы используем её для настройки сортировки запроса по умолчанию:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$sortBy</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">when</span><span class="token punctuation">(</span><span class="token variable">$sortBy</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$sortBy</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token variable">$sortBy</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="сортировка-группировка-ограничение"><a href="#сортировка-группировка-ограничение" class="header-anchor">#</a> Сортировка, группировка, ограничение</h2><h3 id="сортировка"><a href="#сортировка" class="header-anchor">#</a> Сортировка</h3><p>Метод <code>orderBy</code> позволяет отсортировать результаты запроса по указанному столбцу. Первый аргумент метода <code>orderBy</code> — это столбец, по которому вы хотите отсортировать, а второй аргумент управляет направлением сортировки и может быть <code>asc</code> или <code>desc</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;desc&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Методы <code>latest</code> и <code>oldest</code> позволяют легко сортировать результаты по дате. По умолчанию результаты сортируются по столбцу <code>created_at</code>. Или вы можете передать имя столбца, по которому хотите отсортировать.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">latest</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>inRandomOrder</code> может использоваться для случайной сортировки результатов запроса. Например, этот метод можно использовать для получения случайного пользователя.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$randomUser</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">inRandomOrder</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="группировка"><a href="#группировка" class="header-anchor">#</a> Группировка</h3><p>Методы <code>groupBy</code> и <code>having</code> могут использоваться для группировки результатов запроса. Сигнатура метода <code>having</code> аналогична сигнатуре метода <code>where</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">groupBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">having</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете передать несколько аргументов методу <code>groupBy</code> для группировки по нескольким столбцам.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">groupBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;status&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">having</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для более сложных операторов <code>having</code> вы можете использовать метод <code>havingRaw</code>.</p><h3 id="ограничение-и-смещение"><a href="#ограничение-и-смещение" class="header-anchor">#</a> Ограничение и смещение</h3><p>Для ограничения количества результатов, возвращаемых запросом, или для пропуска заданного количества результатов (<code>OFFSET</code>) используйте методы <code>skip</code> и <code>take</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">skip</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">take</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="вставка"><a href="#вставка" class="header-anchor">#</a> Вставка</h2><p>Конструктор запросов также предоставляет метод <code>insert</code> для вставки записей в таблицу базы данных. Метод <code>insert</code> принимает массив имён столбцов и значений для вставки:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">insert</span><span class="token punctuation">(</span>
    <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;john@example.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;votes&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">0</span><span class="token punctuation">]</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы даже можете вставить несколько записей в таблицу одним вызовом <code>insert</code>, передав массив массивов. Каждый массив представляет строку для вставки в таблицу:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">insert</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;taylor@example.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;votes&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dayle@example.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;votes&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">0</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="автоинкрементные-id"><a href="#автоинкрементные-id" class="header-anchor">#</a> Автоинкрементные ID</h3><p>Если таблица имеет автоинкрементный id, используйте метод <code>insertGetId</code> для вставки записи и последующего получения ID:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$id</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">insertGetId</span><span class="token punctuation">(</span>
    <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;john@example.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;votes&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">0</span><span class="token punctuation">]</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>При использовании драйвера базы данных PostgreSQL метод insertGetId ожидает, что автоинкрементный столбец будет называться <code>id</code>. Если вы хотите получить ID из другой «последовательности», вы можете передать имя последовательности вторым параметром метода <code>insertGetId</code>.</p></div><h2 id="обновление"><a href="#обновление" class="header-anchor">#</a> Обновление</h2><p>Помимо вставки записей в базу данных, конструктор запросов может также обновлять существующие записи с помощью метода <code>update</code>. Метод <code>update</code>, как и метод <code>insert</code>, принимает массив пар столбцов и значений, содержащих столбцы для обновления. Вы можете ограничить запрос <code>update</code> с помощью условий <code>where</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;votes&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="обновление-или-вставка"><a href="#обновление-или-вставка" class="header-anchor">#</a> Обновление или вставка</h3><p>Иногда вы можете захотеть обновить существующую запись в базе данных или создать её, если соответствующая запись не существует. В этом сценарии можно использовать метод <code>updateOrInsert</code>. Метод <code>updateOrInsert</code> принимает два аргумента: массив условий для поиска записи и массив пар столбцов и значений, содержащих столбцы для обновления.</p><p>Метод <code>updateOrInsert</code> сначала попытается найти соответствующую запись в базе данных, используя пары столбец/значение первого аргумента. Если запись существует, она будет обновлена значениями второго аргумента. Если запись не найдена, будет вставлена новая запись с объединёнными атрибутами обоих аргументов.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">updateOrInsert</span><span class="token punctuation">(</span>
        <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;john@example.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;John&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;votes&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;2&#39;</span><span class="token punctuation">]</span>
    <span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="upsert"><a href="#upsert" class="header-anchor">#</a> Upsert</h3><p>Метод <code>upsert</code> вставит строки, которые не существуют, и обновит существующие строки новыми значениями. Первый аргумент метода содержит значения для вставки или обновления, второй аргумент перечисляет столбцы, которые уникально идентифицируют записи в таблице. Третий и последний аргумент — массив столбцов, которые должны быть обновлены, если соответствующая запись уже существует в базе данных.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;flights&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">upsert</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;departure&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Oakland&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;destination&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;San Diego&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;price&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">99</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;departure&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Chicago&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;destination&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;New York&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;price&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">150</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;departure&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;destination&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;price&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Все базы данных, кроме SQL Server, требуют, чтобы столбцы во втором аргументе метода <code>upsert</code> имели «primary» или «unique» индекс.</p></div><h3 id="обновление-json-столбцов"><a href="#обновление-json-столбцов" class="header-anchor">#</a> Обновление JSON-столбцов</h3><p>При обновлении JSON-столбца используйте синтаксис <code>-&gt;</code> для доступа к соответствующему ключу в JSON-объекте. Эта операция поддерживается в MySQL 5.7+ и PostgreSQL 9.5+:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$affected</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;options-&gt;enabled&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="инкремент-декремент"><a href="#инкремент-декремент" class="header-anchor">#</a> Инкремент / Декремент</h3><p>Конструктор запросов также предоставляет удобные методы для увеличения или уменьшения значения указанного столбца. Это просто сокращение, предоставляющее более выразительный и лаконичный интерфейс по сравнению с ручным написанием оператора <code>update</code>.</p><p>Оба метода принимают как минимум один аргумент: столбец для изменения. Второй аргумент может быть опционально передан для управления величиной, на которую столбец должен быть увеличен / уменьшен.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">increment</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">increment</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">decrement</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">decrement</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете указать дополнительные столбцы для обновления во время операции:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">increment</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;John&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="удаление"><a href="#удаление" class="header-anchor">#</a> Удаление</h2><p>Конструктор запросов также может использоваться для удаления записей из таблицы с помощью метода <code>delete</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете ограничить операторы <code>delete</code>, добавив условия <code>where</code> перед вызовом метода <code>delete</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&lt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы хотите очистить всю таблицу, что удалит все строки и сбросит автоинкрементный ID на ноль, используйте метод <code>truncate</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">truncate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="пессимистическая-блокировка"><a href="#пессимистическая-блокировка" class="header-anchor">#</a> Пессимистическая блокировка</h2><p>Конструктор запросов также включает несколько функций для выполнения «пессимистической блокировки» в операторах <code>select</code>. Для выполнения оператора с «разделяемой блокировкой» используйте метод <code>sharedLock</code> в запросе. Разделяемая блокировка предотвращает изменение выбранных строк до завершения вашей транзакции.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">sharedLock</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Альтернативно вы можете использовать метод <code>lockForUpdate</code>. Блокировка «for update» предотвращает изменение строк или их выбор с другой разделяемой блокировкой.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">lockForUpdate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="кэширование-запросов"><a href="#кэширование-запросов" class="header-anchor">#</a> Кэширование запросов</h2><p>Вы можете легко кэшировать результаты запроса с помощью <a href="./../services/cache.html">сервиса кэширования</a>. Просто добавьте метод <code>remember</code> или <code>rememberForever</code> в цепочку при подготовке запроса.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">remember</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>В этом примере результаты запроса будут кэшироваться на десять минут. Пока результаты кэшированы, запрос не будет выполняться к базе данных, а результаты будут загружаться из драйвера кэширования по умолчанию, указанного для вашего приложения.</p><h2 id="отладка"><a href="#отладка" class="header-anchor">#</a> Отладка</h2><p>Вы можете использовать методы <code>dd</code> или <code>dump</code> при построении запроса для вывода привязок и SQL запроса. Метод <code>dd</code> отобразит отладочную информацию и затем остановит выполнение запроса. Метод <code>dump</code> отобразит отладочную информацию, но позволит продолжить выполнение запроса:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">dd</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">dump</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4>`,206)),n[2]||(n[2]=s("div",{class:"custom-block also"},[s("ul",null,[s("li",null,[s("a",{href:"https://laravel.com/docs/10.x/queries",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Laravel Query Builder"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])])])])],-1))])}const m=c(r,[["render",k]]);export{q as __pageData,m as default};
